class C1:
    def __init__(self, p, tag):
        self.p = p
        self.tag = tag
    def __eq__(self, other):
        return self.p == other.p
    def __lt__(self, other):
        return self.p < other.p
    def __le__(self, other):
        return self.p <= other.p

x = C1(6, 'x')
y = C1(9, 'y')
print(x == y, x != y, x < y, x <= y)

class C1:
    def __init__(self, val):
        self.val = val
    def __str__(self):
        return 'item:' + str(self.val)
    def __repr__(self):
        return '<' + 'item' + ' ' + str(self.val) + '>'

obj = C1(6)
print(str(obj), repr(obj))

